/// ```text
/// Open { $section }
/// ```
pub fn settings_open_section(section: &str) -> String {
    crate::active::message(322, &[("section", Arg::Str(section))])
}

/// ```text
/// { $count ->
///     [one] { $count } font
///    *[other] { $count } fonts
/// }
/// ```
pub fn settings_font_count(count: i64) -> String {
    crate::active::message(323, &[("count", Arg::Int(count))])
}

/// ```text
/// { $count ->
///     [one] { $count } space
///    *[other] { $count } spaces
/// }
/// ```
pub fn settings_tab_width(count: i64) -> String {
    crate::active::message(324, &[("count", Arg::Int(count))])
}

/// Each message with variables formatted with sample arguments: text as `Sample`, numbers as 1 and
/// 5, so a plural shows both of English's forms.
#[cfg(feature = "test-support")]
pub fn samples() -> Vec<(&'static str, String)> {
    vec![
        ("settings-open-section", settings_open_section("Sample")),
        ("settings-font-count", settings_font_count(1)),
        ("settings-font-count", settings_font_count(5)),
        ("settings-tab-width", settings_tab_width(1)),
        ("settings-tab-width", settings_tab_width(5)),
    ]
}
